#!/bin/bash
# 台への着地の後の胴の減衰（jb70、§34）: jb19 の JS05 に KP_TRUNK_LAND_BOX・KD_TRUNK_LAND_BOX 60・60（KD60）と 200・100（KD100）、種 27182 N=16 と種 16180 N=8 で 5・7.5・10 cm、j68。jb69: jb19 の JS05 に KP_TRUNK_LAND_BOX 60・KD_TRUNK_LAND_BOX 15（KTB60）、種 27182 N=16（jb19・jb20 と同じ本）と種 16180 N=8（jb18・jb21 と同じ本）で 5・7.5・10 cm、j68。jb20: jb19 の JS05 に KP_TRUNK_LAND 60・KD_TRUNK_LAND 15（KT60、5・7.5・10 cm）と 100・20（KT100、5 cm）、種 27182、N=16、j67。jb19: jb18 の JS05（JT30＋LAND_REF_SOLES 0.5）を種 27182、N=16（jb13・jb17 と同じ本）で 5・7.5・10 cm、j67。jb18: jb17 の JT30 に LAND_REF_SOLES 0.5・1.0、5 cm と 10 cm、種 16180、N=8。jb17: jb16 の JT30（JUMP_BOX_V 3.0、JUMP_BOX_V_TABS、JUMP_BOX_TUCK 0.10）を 5・7.5 cm（種 16180、N=8、jb12・jb14 と同じ本）と 10 cm の種 27182（N=16、jb13 と同じ本）で、j66。jb16: jb15 の JV に JUMP_BOX_V_TABS 1、JUMP_BOX_V 2.5・2.75・3.0、j66。jb15: jb14 の JH10T（10 cm、JUMP_BOX_TUCK 0.10）に JUMP_BOX_V 2.5・3.0 と JUMP_BOX_CROUCH 0.16（既定 0.12）、j65。jb14: 基準 BX（jb13 の JR1_ と同じ設定、j64 = base_bx）で台の高さだけ 0.075・0.10 に。0.10 は JUMP_BOX_TUCK 0.05（BX のまま）と 0.10（足を上げる量を台の高さに合わせる）。台 0.20・0.30・0.40・0.60、1.5・2.0、N=8、種 16180（jb12 の JQ1_ と同じ本）。
D=/home/takara/work/dp/articara/log/claude_g1jump_20261021; B=$D/g1_flight_probe_j68
X='"JUMP_ABORT":"1","JUMP_PUSH_R":"0.3","QD_CLAMP":"40","DIAG_TD":"1","FLIGHT_FEET_FLAT":"1","DIAG_HX":"1","RELEASE_FIRST_OFF":"1","WBCW_CONTACT_REST":"0.1","WBCW_TRUNK_LAND":"0.03","FALL_TILT":"1.5","LAND_REF_FOLLOW":"2","AIR_ABORT_T":"0.08"'
H=',"FLIGHT_FEET_CAPTURE_T":"0.06","KP_FLIGHT_FEET":"1000","KD_FLIGHT_FEET":"63","WBCW_TRUNK_PUSH":"0.003","WBCW_MOMENTUM":"10","WBCW_CONTACT":"100","WBCW_TRUNK_LAND_VZ":"0","JUMP_H_NAT":"1","WBCW_CONTACT_REST_LAUNCH":"1","FLIGHT_FEET_CAPTURE":"0.55","FLIGHT_TRUNK":"0","FLIGHT_FEET_W":"10","WBCW_MOMENTUM_PUSH":"1","MU_TORSION":"0.02","TRUNK_RP_YAWED":"1"'
TB=',"JUMP_VX_TAB":"1.0:1.0,1.5:1.2,2.0:1.6","JUMP_LEAN_TAB":"1.0:0,1.5:0.045,2.0:0.06"'
R=',"JUMP_REPEAT":"5","JUMP_REPEAT_RECENTRE":"1","JUMP_REPEAT_SOFT_CROUCH":"1","FLIGHT_FEET_WIDTH":"0.236","WBCW_TRUNK_LAND_T":"1.0","T":"24","FLIGHT_FEET_YAW":"1"'
FT='1.5|0:-0.112,0.25:-0.026,0.4:0.021,0.5:0.068,0.55:0.090,0.6:0.124,0.65:0.230,0.7:0.265,0.85:0.290,1.0:0.334,1.1:0.347;2.0|0:-0.148,0.25:-0.026,0.4:0.038,0.5:0.104,0.55:0.131,0.6:0.161,0.65:0.216,0.7:0.249,0.75:0.271,0.85:0.325,1.0:0.362'
cd $D
# run TAG BOX TUCK
run() { TAG=$1 SEED=16180 BIN=$B CONDS=1.5,2.0 N=8 W=1 EXTRA="{$X$H$TB$R,\"JUMP_FWD_TAB\":\"$FT\",\"JUMP_BOX_TUCK\":\"$3\",\"JUMP_BOX\":\"$2\",$M}" python3 jrand.py; }
M='"JUMP_BOX_GAP":"0.10","JUMP_BOX_GAP_TOL":"0.025","JUMP_BOX_S":"1.2","JUMP_BOX_CROUCH_W":"1"'
M="$M,\"JUMP_BOX_V\":\"3.0\",\"JUMP_BOX_V_TABS\":\"1\""
M="$M,\"LAND_REF_SOLES\":\"0.5\""
kt() { # TAG BOX_H SEED N KP KD
  for b in 20 30 40 60; do
    (TAG=$1_$b SEED=$3 BIN=$B CONDS=1.5,2.0 N=$4 W=1 EXTRA="{$X$H$TB$R,\"JUMP_FWD_TAB\":\"$FT\",\"JUMP_BOX_TUCK\":\"0.10\",\"JUMP_BOX\":\"0.$b,$2\",$M,\"KP_TRUNK_LAND_BOX\":\"$5\",\"KD_TRUNK_LAND_BOX\":\"$6\"}" python3 jrand.py) &
  done
}
kt KD60s5 0.05 27182 16 60 60; kt KD60s75 0.075 27182 16 60 60; kt KD60s10 0.10 27182 16 60 60
wait
kt KD60h5 0.05 16180 8 60 60; kt KD60h75 0.075 16180 8 60 60; kt KD60h10 0.10 16180 8 60 60
wait
kt KD100s5 0.05 27182 16 200 100; kt KD100s75 0.075 27182 16 200 100; kt KD100s10 0.10 27182 16 200 100
wait
kt KD100h5 0.05 16180 8 200 100; kt KD100h75 0.075 16180 8 200 100; kt KD100h10 0.10 16180 8 200 100
wait
for p in KD60s5 KD60s75 KD60s10 KD60h5 KD60h75 KD60h10 KD100s5 KD100s75 KD100s10 KD100h5 KD100h75 KD100h10; do python3 jbsumm.py ${p}_20 ${p}_30 ${p}_40 ${p}_60; done
for k in KD60 KD100; do for h in 5 75 10; do python3 pairchurn.py JS05s$h ${k}s$h; python3 pairchurn.py JS05h$h ${k}h$h; done; done
echo "#### JB70_DONE"
